import numpy as np

def loss_function(x):
    return (x - 3) ** 2  # minimum at x = 3

def gradient(x):
    return 2 * (x - 3)

x = 0.0  # starting point, far from the true minimum
learning_rate = 0.1
steps = 20

print(f"Starting at x = {x}")
for step in range(steps):
    grad = gradient(x)
    x = x - learning_rate * grad  # the exact update rule covered in this topic
    if step % 4 == 0:
        print(f"Step {step}: x = {x:.4f}, loss = {loss_function(x):.4f}")

print(f"\nFinal x = {x:.4f} (true minimum is at x = 3)")
print("Each step moved x in the direction that reduces the loss, exactly the core idea covered in this topic")
